const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'₹'+Math.round(n).toLocaleString('en-IN'),size=p=>`${Math.round(p.w*100)} × ${Math.round(p.d*100)} × ${Math.round(p.h*100)} cm`;
const storageOptions=storageConfig(location),key=storageOptions.key;let state=initialState(),tab='room',undo=[],saveTimer,toastTimer,server=false,saving=false,needsSave=false,dimensions=true,kitchenPanelFocus='both';
const allowedTypes=['sofa','woodsofa','chaise','chair','table','rug','console','ottoman','lamp','screen','sidetable','tv','soundbar','diningtable','diningchair','cabinet','pendant','art','artset','tablelamp','decor',...kitchenTypes];
const safeURL=value=>{try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return ''}};
const layout=()=>state.layouts.find(l=>l.id===state.active)||state.layouts[0];
const activeRoom=()=>roomOf(layout()),info=()=>roomInfo[activeRoom()];
const inRoom=p=>p.room?p.room===activeRoom():activeRoom()==='living';
const roomShortlist=()=>state.shortlist.filter(s=>{const p=product(s.id);return p&&inRoom(p)});
function saveRoom(){state.rooms??={};state.rooms[activeRoom()]={note:state.roomNote,finalised:state.finalised,lastLayout:state.active};}
function openLayout(id){saveRoom();state.active=id;const r=state.rooms[activeRoom()];state.roomNote=r?.note||'';state.finalised=!!r?.finalised;state.selected=null;tab='room';persist();render();scene.setView(state.view);if(layout().utilityPlan)setKitchenFocus('utility');}
function contextItems(){return ['living','dining','kitchen'].filter(r=>r!==activeRoom()).flatMap(r=>(state.layouts.find(l=>l.id===state.rooms?.[r]?.lastLayout)||state.layouts.find(l=>roomOf(l)===r))?.items||[]);}
const product=id=>[...products,...electronicsProducts,...state.customProducts].find(p=>p.id===id);
function productLink(item,extra=''){const custom=joineryFor(item);if(custom)return `<button class="custom-spec-link" data-custom-spec="${esc(custom.id)}" aria-label="Custom specs: ${esc(custom.name)}">Custom specs ↗</button>`;const url=safeURL(item.url||product(item.productId||item.referenceId)?.url);if(!url)return `<small class="unsourced-item">Size study · no product chosen</small>`;const label=item.productId||!item.referenceId?'View product':'Original product';return `<a class="product-link ${extra}" href="${esc(url)}" target="_blank" rel="noopener noreferrer" aria-label="${esc(label+': '+item.name)}">${label} ↗</a>`;}
const joineryFor=item=>state.customFurniture?.find(c=>c.referenceId===item.referenceId);
const uid=()=>crypto.randomUUID();
function normalise(raw){
 if(raw?.schema!==1||!Array.isArray(raw.layouts)||!raw.layouts.length||raw.layouts.length>20)throw Error('This is not a valid room workspace backup.');
 const clean=initialState();clean.revision=Number.isFinite(raw.revision)?raw.revision:1;
 const cleanItem=i=>{if(!i||!allowedTypes.includes(i.type))throw Error('Unrecognised furniture type.');for(const n of ['w','d','h'])if(!Number.isFinite(i[n])||i[n]<.005||i[n]>10)throw Error('Invalid furniture dimensions.');for(const n of ['x','z','rotation'])if(!Number.isFinite(i[n])||Math.abs(i[n])>10000)throw Error('Invalid furniture position.');return {id:String(i.id||uid()).slice(0,100),name:String(i.name||'Furniture').slice(0,120),brand:String(i.brand||'Size study').slice(0,100),type:i.type,room:['dining','kitchen'].includes(i.room)?i.room:'living',zone:i.zone==='utility'?'utility':'kitchen',role:String(i.role||'').slice(0,40),applianceIds:Array.isArray(i.applianceIds)?i.applianceIds.filter(v=>typeof v==='string').slice(0,10):[],pendingAppliance:!!i.pendingAppliance,finishPalette:kitchenFinishes[i.finishPalette]?i.finishPalette:null,category:i.category==='electronics'||['tv','soundbar'].includes(i.type)?'electronics':'furniture',elevation:Number.isFinite(i.elevation)?Math.max(0,Math.min(2.5,i.elevation)):0,mount:i.mount==='stand'?'stand':'wall',w:i.w,d:i.d,h:i.h,x:i.x,z:i.z,rotation:i.rotation,productId:typeof i.productId==='string'?i.productId:null,referenceId:String(i.referenceId||''),locked:!!i.locked,verified:!!i.verified,color:/^#[a-f\d]{6}$/i.test(i.color)?i.color:'#c7b9a2',price:Number.isFinite(i.price)&&i.price>=0&&i.price<1e8?i.price:null,url:safeURL(i.url),image:typeof i.image==='string'&&/^[a-z0-9-]+\.jpg$/.test(i.image)?i.image:null,detail:String(i.detail||'').slice(0,1000)};};
 clean.layouts=raw.layouts.map(l=>{if(!Array.isArray(l.items)||l.items.length>100)throw Error('Too many pieces in a layout.');const items=l.items.map(cleanItem);if(new Set(items.map(i=>i.id)).size!==items.length)throw Error('Duplicate furniture IDs in a layout.');return {id:String(l.id||uid()).slice(0,100),name:String(l.name||'Saved layout').slice(0,100),room:['dining','kitchen'].includes(l.room)?l.room:'living',kitchenScheme:['parallel','pantry','island','utility'].includes(l.kitchenScheme)?l.kitchenScheme:null,breakfastMode:!!l.breakfastMode,appliancePlan:!!l.appliancePlan,utilityPlan:!!l.utilityPlan,utilitySource:String(l.utilitySource||''),kitchenFinish:kitchenFinishes[l.kitchenFinish]?l.kitchenFinish:null,scheme:['sunlit','quiet','evening'].includes(l.scheme)?l.scheme:null,guestMode:!!l.guestMode,subtitle:String(l.subtitle||'').slice(0,200),heroImage:typeof l.heroImage==='string'&&/^[a-z0-9-]+\.jpg$/.test(l.heroImage)?l.heroImage:null,project:projects.some(p=>p.id===l.project)?l.project:'poetry',description:String(l.description||'Your saved arrangement.').slice(0,700),passageOption:['clear','pouf','ctable'].includes(l.passageOption)?l.passageOption:null,sourceLayout:String(l.sourceLayout||''),items};});
 if(new Set(clean.layouts.map(l=>l.id)).size!==clean.layouts.length)throw Error('Duplicate layout names.');
 clean.active=clean.layouts.some(l=>l.id===raw.active)?raw.active:clean.layouts[0].id;clean.view=['plan','cutaway','eye','overall'].includes(raw.view)?raw.view:'cutaway';clean.selected=clean.layouts.find(l=>l.id===clean.active).items.some(i=>i.id===raw.selected)?raw.selected:null;clean.updatedAt=Number.isFinite(raw.updatedAt)?raw.updatedAt:Date.now();clean.finalised=!!raw.finalised;clean.roomNote=String(raw.roomNote||'').slice(0,4000);
 clean.customProducts=(Array.isArray(raw.customProducts)?raw.customProducts:[]).slice(0,100).map(p=>({...cleanItem({...p,x:0,z:0,rotation:0}),locked:false,verified:false,brand:p.pendingAppliance?'Planning allowance · model pending':'Your saved option'}));
 const valid=new Set([...products,...clean.customProducts].map(p=>p.id));
 const electronicIds=new Set([...electronicsProducts,...clean.customProducts.filter(p=>p.category==='electronics')].map(p=>p.id));
 clean.electronics=(Array.isArray(raw.electronics)?raw.electronics:clean.electronics).filter(e=>electronicIds.has(e.id)).map(e=>({id:e.id,status:['Size reference','Considering','Favourite','Chosen','Pass'].includes(e.status)?e.status:'Considering',note:String(e.note||'').slice(0,2000)}));clean.shortlist=(Array.isArray(raw.shortlist)?raw.shortlist:[]).filter(s=>valid.has(s.id)).map(s=>({id:s.id,status:['Considering','Favourite','Chosen','Pass'].includes(s.status)?s.status:'Considering',note:String(s.note||'').slice(0,2000)}));
 clean.customFurniture=(Array.isArray(raw.customFurniture)?raw.customFurniture:[]).slice(0,100).map(c=>({id:String(c.id||uid()).slice(0,100),name:String(c.name||'Custom furniture').slice(0,120),referenceId:String(c.referenceId||'').slice(0,100),finishStudy:kitchenFinishes[c.finishStudy]?c.finishStudy:null,room:String(c.room||'Living / dining').slice(0,100),w:Number.isFinite(c.w)&&c.w>0&&c.w<10?c.w:1.45,d:Number.isFinite(c.d)&&c.d>0&&c.d<10?c.d:.08,h:Number.isFinite(c.h)&&c.h>0&&c.h<10?c.h:2.1,status:['Concept','Ready for quote','Quoted','Approved','In production','Installed'].includes(c.status)?c.status:'Concept',material:String(c.material||'').slice(0,2000),finish:String(c.finish||'').slice(0,2000),design:String(c.design||'').slice(0,3000),fixing:String(c.fixing||'').slice(0,2000),supplier:String(c.supplier||'').slice(0,200),quote:Number.isFinite(c.quote)&&c.quote>=0&&c.quote<1e8?c.quote:null,notes:String(c.notes||'').slice(0,4000)}));
 clean.rooms={};for(const id of ['living','dining','kitchen']){const r=raw.rooms?.[id];if(r)clean.rooms[id]={note:String(r.note||'').slice(0,4000),finalised:!!r.finalised,lastLayout:String(r.lastLayout||'').slice(0,100)};}
 if(clean.revision<4&&clean.customFurniture.length===0)delete clean.customFurniture;
 return clean;
}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3000);}
function remember(){undo.push(JSON.stringify(state));if(undo.length>30)undo.shift();$('#undo').disabled=false;}
function change(fn,message){remember();fn();persist();render();if(message)toast(message);}
function persist(){saveRoom();state.updatedAt=Date.now();try{localStorage.setItem(key,JSON.stringify(state))}catch{$('#save-state').textContent='Export a backup to save';}clearTimeout(saveTimer);$('#save-state').textContent=server?'Saving locally…':'Saved in this browser';saveTimer=setTimeout(flush,300);}
async function flush(){if(!server)return;if(saving){needsSave=true;return;}saving=true;needsSave=false;const payload=JSON.stringify(state);try{const r=await fetch(storageOptions.api,{method:'POST',headers:{'Content-Type':'application/json'},body:payload});if(!r.ok)throw Error();$('#save-state').textContent='Saved locally ✓';}catch{$('#save-state').textContent='Browser copy saved · export backup';}finally{saving=false;if(needsSave)flush();}}
async function load(){const loaded=await readWorkspace({config:storageOptions,storage:{getItem:k=>localStorage.getItem(k)},fetcher:fetch,normalise});server=loaded.server;state=upgradeWorkspace(loaded.state||state);for(const l of state.layouts)for(const i of l.items){const p=[...products,...electronicsProducts].find(p=>p.id===i.productId);if(p&&i.locked){i.price=p.price;i.image||=p.image;}}render();scene.setView(state.view);if(layout().utilityPlan)setKitchenFocus('utility');persist();document.body.dataset.ready='true';}
const scene=createScene($('#scene'),{select(id){state.selected=id;const item=layout().items.find(i=>i.id===id);if(item?.category==='electronics')tab='electronics';else if(item)tab='room';scene.select(id);renderInspector();renderList();document.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-selected',String(tab===b.dataset.tab)));$('#drag-tip').hidden=!id||state.view==='eye';},move(id,x,z,done){const item=layout().items.find(i=>i.id===id);if(!item)return;item.x=Math.round(x*100)/100;item.z=Math.round(z*100)/100;state.finalised=false;scene.move(id,item.x,item.z);const xi=$('#position-x'),zi=$('#position-z');if(xi)xi.value=Math.round((item.x-info().x0)*100);if(zi)zi.value=Math.round((item.z-info().z0)*100);renderChecks();if(done){persist();render();}},commit(phase){if(phase==='before')remember();else{persist();render();}}});
function thumb(p){return `<div class="furniture-thumb">${p.image?`<img src="assets/images/${esc(p.image)}" alt="${esc(p.name)}" loading="lazy" onerror="this.hidden=true">`:`<svg viewBox="0 0 90 70" aria-hidden="true"><path d="M15 46L45 59 76 43 46 30Z" fill="${esc(p.color||'#b8a688')}" opacity=".35"/><path d="M17 37L45 50 73 35 46 22Z" fill="${esc(p.color||'#b8a688')}"/><path d="M17 37v9L45 59v-9m28-15v9L45 59" fill="none" stroke="#8e957d" stroke-width="1"/></svg>`}</div>`;}
function render(){
 const l=layout(),room=activeRoom(),ri=info(),isOverall=state.view==='overall';document.body.dataset.overall=String(isOverall);$('#overall-room-nav').hidden=!isOverall;
 $('#room-name').textContent=ri.name;$('#room-index').textContent=ri.index;$('#room-size').textContent=ri.size;$('#direction-heading').textContent=room==='kitchen'?'Modular layout studies':room==='dining'?'Three complete room ideas':'Three ways to live here';$('#room-brief').innerHTML='Table & chairs · crockery storage<br>Lighting, art & finishing touches';
 if(room==='kitchen')$('#room-brief').innerHTML='Kitchen cabinetry + utility<br>Appliance models to add later';$('#room-brief').hidden=room==='living';$('#kitchen-focus').hidden=room!=='kitchen'||isOverall;$('#add-item').textContent=room==='kitchen'?'＋ Add a cabinet module':'＋ Add furniture or save a link';document.body.dataset.room=room;$('#pricing-note').textContent=room==='kitchen'?'Custom cabinetry concepts. Maker quotes pending. Countertop, hardware, services and appliance choices are open; no appliance costs assumed.':room==='dining'?'Listed prices checked 20 Oct 2026. Furniture, lights and art included. Paint, styling, bulbs, electrical work, delivery and assembly extra. Bengaluru stock needs your pincode.':'Listed prices checked 20 Oct 2026. Delivery, assembly and unpriced pieces extra. TV price still open. Bengaluru stock needs your pincode.';$('#reference-note-copy').innerHTML=room==='kitchen'?'Custom layouts for your flat.<br>Linked kitchen references for finishes.':room==='dining'?'Light timber and soft upholstery.<br>Following your lounge palette.':'Inspired by real Indian homes.<br>Adapted to your floor plan.';
 renderKitchenFinishes();$('#scene').setAttribute('aria-label',isOverall?'Overall apartment floor plan':'Interactive '+ri.name.toLowerCase()+' furniture planner');document.querySelector('.compass span').textContent=room==='kitchen'?'TO DINING':room==='dining'?'BEDROOM SIDE':'BALCONY';
 document.querySelectorAll('[data-room]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.room===room)));
 const card=(v,i)=>{if(v.kitchenScheme){const k=kitchenIdeas[v.kitchenScheme],finish=kitchenFinishes[v.kitchenFinish];return `<article class="direction kitchen-direction ${v.id===state.active?'active':''}"><button data-layout="${esc(v.id)}" aria-pressed="${v.id===state.active}" aria-label="Open ${esc(v.name)}"><div class="kitchen-card-preview">${kitchenThumbnail(v)}<span class="direction-tag">${v.utilityPlan?'YOUR UTILITY BRIEF':v.appliancePlan?'YOUR APPLIANCE BRIEF':v.kitchenScheme==='parallel'?'EARLIER STUDY':'LAYOUT STUDY'}</span></div><div class="direction-info"><div class="direction-name">${esc(v.name.replace(/^\d+ · /,''))}<span>${v.id===state.active?'✓':'↗'}</span></div><small>${esc(v.subtitle)}</small><div class="scheme-card-bottom"><span class="palette-dots">${(finish?[finish.base,finish.upper,finish.top]:k.swatches).map(c=>`<i style="background:${c}"></i>`).join('')}</span><span>Quote pending</span></div></div></button></article>`;}const p=projects.find(p=>p.id===v.project),custom=room==='living'&&i>2,photo=v.heroImage||p.image,palette=schemePalettes[v.scheme],total=v.items.filter(i=>Number.isFinite(i.price)).reduce((s,i)=>s+i.price,0);return `<article class="direction ${v.id===state.active?'active':''} ${custom?'custom-direction':''} ${room==='dining'?'dining-direction':''} ${palette?'complete-scheme':''}"><button data-layout="${esc(v.id)}" aria-pressed="${v.id===state.active}" aria-label="Open ${esc(v.name)}">${custom?'':`<div class="direction-photo"><img src="assets/images/${esc(photo)}" alt="${esc(palette?'Mood reference · '+p.title:v.subtitle||p.title)}" loading="lazy">${palette?'<span class="direction-tag">MOOD REFERENCE</span>':v.id==='lounge'?'<span class="direction-tag">YOUR STARTING PICK</span>':''}</div>`}<div class="direction-info"><div class="direction-name">${esc(v.name.replace(/^\d+ · /,''))}<span>${v.id===state.active?'✓':'↗'}</span></div><small>${esc(v.subtitle||(custom?'Your saved layout':p.studio))}</small>${palette?`<div class="scheme-card-bottom"><span class="palette-dots">${palette.swatches.map(c=>`<i style="background:${c}"></i>`).join('')}</span><span>${money(total)} <em>priced pieces</em></span></div>`:''}</div></button></article>`;};
 const roomLayouts=state.layouts.filter(v=>roomOf(v)===room),schemes=roomLayouts.filter(v=>v.scheme&&!v.guestMode),earlier=roomLayouts.filter(v=>!v.scheme||v.guestMode);
 $('#directions').innerHTML=room==='kitchen'?roomLayouts.filter(v=>!v.sourceLayout).sort((a,b)=>Number(!!b.utilityPlan)-Number(!!a.utilityPlan)||Number(!!b.appliancePlan)-Number(!!a.appliancePlan)).map(card).join('')+(roomLayouts.some(v=>v.sourceLayout)?`<details class="earlier-layouts" open><summary>Saved variations</summary>${roomLayouts.filter(v=>v.sourceLayout).map(card).join('')}</details>`:''):room==='dining'?schemes.map(card).join('')+`<details class="earlier-layouts" ${earlier.some(l=>l.id===state.active)?'open':''}><summary>Saved layouts & size studies · ${earlier.length}</summary>${earlier.map(card).join('')}</details>`:roomLayouts.map(card).join('');
 $('#utility-details').hidden=!l.utilityPlan;$('#scheme-details').hidden=!l.scheme&&!l.kitchenScheme;$('#scheme-details').textContent=l.kitchenScheme?'Layout & cabinet brief ↗':'Room details ↗';$('#breakfast-study').hidden=l.kitchenScheme!=='island';$('#breakfast-study').textContent=l.breakfastMode?'Back to prep island ↗':'Try breakfast seating ↗';$('#reference-button').innerHTML=room==='kitchen'?(l.kitchenFinish?'Finish references ↗':'See kitchen reference ↗'):'See the real home <span>↗</span>';$('#six-seat').hidden=!l.scheme||l.scheme==='sunlit';$('#six-seat').textContent=l.guestMode?'Back to four seats ↗':'Six-seat check ↗';
 $('#scene-badge-text').textContent=isOverall?'Full apartment · walls sectioned at 1.2 m':l.kitchenScheme?'Proposed cabinetry · appliance spaces provisional':l.scheme?'Complete room study · builder dimensions':'Sizes from your builder’s plan';
 $('#layout-title').textContent=isOverall?'Your whole apartment':l.name.replace(/^\d+ · /,'');$('#layout-description').textContent=isOverall?'Showing each room’s current saved layout together. Bedrooms and bathrooms are unfurnished. Builder dimensions are provisional internal sizes; unlabelled openings are scaled estimates. Main bedroom flooring remains undecided.':l.description;$('#room-note').value=state.roomNote;
 $('#finalise').innerHTML=state.finalised?'Room finalised · Reopen <span>↶</span>':'Mark room as finalised <span>✓</span>';
 $('#footer-status').textContent=isOverall?'OVERVIEW · WHOLE APARTMENT':(state.finalised?'FINALISED':'EXPLORING')+' · '+ri.name.toUpperCase();$('#room-count').textContent=l.items.filter(i=>i.category!=='electronics').length;$('#short-count').textContent=roomShortlist().length;$('#electronics-count').textContent=state.electronics.length;$('#custom-count').textContent=state.customFurniture.length;$('#passage-options').hidden=!l.items.some(i=>i.type==='chaise');
 document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===state.view);b.setAttribute('aria-pressed',b.dataset.view===state.view)});
 document.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-selected',String(tab===b.dataset.tab)));
 $('#undo').disabled=!undo.length;$('#drag-tip').hidden=!state.selected||state.view==='eye';renderInspector();renderList();renderChecks();scene.update(l,state.selected,contextItems(),state.layouts.find(v=>v.id===state.rooms?.dining?.lastLayout)?.scheme);
 const priced=l.items.filter(i=>Number.isFinite(i.price));$('#priced-total').textContent=room==='kitchen'?'Quote pending':money(priced.reduce((s,i)=>s+i.price,0));document.querySelector('.budget-summary .overline').textContent=room==='kitchen'?'CUSTOM CABINETRY':'PRICED PIECES IN THIS LAYOUT';const n=l.items.length-priced.length;$('#unpriced').textContent=room==='kitchen'?'Compare alternatives · do not add their quotes together':n?`+ ${n} unpriced ${n===1?'piece':'pieces'} · Not a room quote`:'Product prices only · Not a room quote';
}
function finishLinks(id){const p=kitchenFinishes[id];return p?p.references.map(r=>`<a href="${r.url}" target="_blank" rel="noopener noreferrer">${esc(r.name)} ↗</a>`).join(' · '):'';}
function setKitchenFocus(id){kitchenPanelFocus=id;document.querySelectorAll('[data-focus]').forEach(v=>v.setAttribute('aria-pressed',String(v.dataset.focus===id)));renderList();scene.focus(id);}
function renderKitchenFinishes(){const el=$('#kitchen-finishes'),caption=$('#kitchen-finish-caption');el.hidden=activeRoom()!=='kitchen';caption.hidden=el.hidden;if(el.hidden)return;const l=layout(),p=kitchenFinishes[l.kitchenFinish];caption.textContent=p?'Cabinet preview · '+p.name:'Choose a cabinet colour preview';el.innerHTML=`<div class="finish-heading"><h3>Cabinet colours</h3><span>SAME LAYOUT</span></div><div class="finish-options">${Object.entries(kitchenFinishes).map(([id,p])=>`<button data-kitchen-finish="${id}" aria-pressed="${l.kitchenFinish===id}" aria-label="Preview ${p.name}"><span class="finish-pair"><i style="background:${p.base}" class="${p.wood?'grain':''}"></i><i style="background:${p.upper}"></i></span><span class="finish-option-copy"><strong>${p.name}</strong><small>${p.tag}</small></span><span class="finish-tick">${l.kitchenFinish===id?'✓':'↗'}</span></button>`).join('')}</div>${p?`<p class="finish-description">${esc(p.description)}</p><div class="finish-source-links">${finishLinks(l.kitchenFinish)}</div><button class="text-link" id="finish-details">Colours, materials & references ↗</button>`:'<p class="finish-description">Preview one of three neutral options above.</p>'}<p class="finish-disclaimer">Approximate screen colours · final samples to approve</p><div class="finish-layout-heading">LAYOUT OPTIONS</div>`;}
function showFinishDetails(){const id=layout().kitchenFinish||'sand',p=kitchenFinishes[id];openModal(p.name+' · finish direction',`<div class="finish-large-swatches">${[[p.base,'Lower + tall cabinets'],[p.upper,'Upper cupboards'],[p.top,'Worktop study']].map(([c,label])=>`<div><i style="background:${c}"></i><span>${label}</span></div>`).join('')}</div><p>${esc(p.description)}</p><h3>Real finish references</h3>${p.references.map(r=>`<p class="finish-ref"><a href="${r.url}" target="_blank" rel="noopener noreferrer">${r.name} ↗</a><small>${r.kind}</small></p>`).join('')}<h3>Worktop and hardware</h3><p>${p.worktop}. The worktop product has not been selected. Neutral dark handles / hood and the existing tile study stay consistent across the comparisons. Wood-grain rendering is illustrative; the actual product grain and colour are shown in the linked manufacturer references.</p><h3>Choosing the finish</h3><p>These are colour directions for custom cabinetry. IKEA fronts are system components; their colour reference does not establish compatibility with the proposed custom modules. Greenlam laminate needs an appropriate substrate, edge detail and installation specification. Obtain physical samples and compare them beside your actual floor tile, backsplash and timber furniture in daylight and evening light. The floor colour is still a study.</p><p class="fine">The selected preview saves with this layout and is tracked in its Custom furniture package. Prices, Bengaluru stock, exact shade match, surface specification and final approval remain open. Changing the palette preserves cabinet sizes, appliance allocations and clearances.</p>`,'KITCHEN / REAL FINISH REFERENCES');}
function renderChecks(){const problems=checks(layout().items,activeRoom());if(activeRoom()==='kitchen'){const d=kitchenClearance(layout().items);$('#fit-status').textContent=problems.length?`${problems.length} placement checks to review`:layout().utilityPlan?'Footprints clear · appliance / site checks pending':layout().appliancePlan?'Footprints clear · wall / duct check pending':'Concept routes clear · site measure pending';$('#fit-detail').textContent=`Working gap ≈ ${d.working===null?'—':Math.round(d.working*100)} cm · Utility gap ≈ ${d.utility===null?'—':Math.round(d.utility*100)} cm${d.end===null?'':` · Island end ≈ ${Math.round(d.end*100)} cm`}`;if(layout().utilityPlan){const open=utilityOpeningClearance(layout().items);$('#fit-detail').textContent=`Utility aisle ≈ ${d.utility===null?'—':Math.round(d.utility*100)} cm · Dishwasher 60 cm opening study: ≈ ${open.dishwasher===null?'—':Math.round(open.dishwasher*100)} cm remaining`;}document.querySelector('.planning-strip .status-dot').style.background=problems.length?'#b58d5d':'#80956b';return;}if(activeRoom()==='dining'){const d=diningClearance(layout().items);$('#fit-status').textContent=problems.length?'Clearance to review':'Daily layout · passage guide clear';$('#fit-detail').textContent=`South gap: ≈ ${Math.round(d.seated*100)} cm behind chairs / furniture · ≈ ${Math.round(d.pulled*100)} cm with 35 cm pull-back`;document.querySelector('.planning-strip .status-dot').style.background=problems.length?'#b58d5d':'#80956b';return;}$('#fit-status').textContent=problems.length?`${problems.length} ${problems.length===1?'thing':'things'} to check`:'No footprint overlaps';$('#fit-detail').textContent=problems.length?'Review placement before choosing a layout.':`Dining turn ≈ ${Math.round(passageGap(layout().items)*100)} cm · 60 cm balcony guide clear`;document.querySelector('.planning-strip .status-dot').style.background=problems.length?'#b58d5d':'#80956b';}
function renderList(){
 const container=$('#right-content');
 if(tab==='room'){
  const items=layout().items.filter(i=>i.category!=='electronics');
  const row=i=>`<article class="furniture-row ${state.selected===i.id?'selected':''}">${thumb(i)}<div class="furniture-info"><button class="furniture-title" data-select="${esc(i.id)}" aria-label="Edit ${esc(i.name)}"><strong>${esc(i.name)}</strong><small>${i.type==='artset'?'Two prints · grouped hanging study':i.type==='art'?`${Math.round(i.w*100)} × ${Math.round(i.h*100)} cm · wall art`:`${Math.round(i.w*100)} × ${Math.round(i.d*100)} cm · ${kitchenTypes.includes(i.type)?(raisedKitchen.includes(i.type)?'Raised module':'Proposed module'):i.locked?'Product size':'Adjustable study'}`}</small><span class="row-price">${Number.isFinite(i.price)?money(i.price):kitchenTypes.includes(i.type)?'Custom · quote pending':'Price open'}${i.type==='artset'?' / pair':''}</span></button>${productLink(i)}</div><div class="row-actions"><button class="icon" data-select="${esc(i.id)}" aria-label="Select ${esc(i.name)}">↗</button><button class="icon" data-remove="${esc(i.id)}" aria-label="Remove ${esc(i.name)}">×</button></div></article>`;
  const groups=[['Dining & seating',['diningtable','diningchair']],['Crockery storage',['cabinet']],['Lighting',['pendant','tablelamp','lamp']],['Art & finishing touches',['art','artset','decor']]];
  groups.push(['Other pieces',[...new Set(items.filter(i=>!groups.some(([,types])=>types.includes(i.type))).map(i=>i.type))]]);
  if(activeRoom()==='kitchen'){container.innerHTML=(kitchenPanelFocus==='utility'?['utility','kitchen']:['kitchen','utility']).map(zone=>`<section class="room-product-group"><h3>${zone==='kitchen'?'Kitchen · cabinets & reserves':'Utility · wash, laundry & storage'}</h3>${items.filter(i=>i.zone===zone).map(row).join('')}</section>`).join('');}else container.innerHTML=layout().scheme?groups.map(([title,types])=>{const list=items.filter(i=>types.includes(i.type));return list.length?`<section class="room-product-group"><h3>${title}</h3>${list.map(row).join('')}</section>`:''}).join(''):items.map(row).join('');
  if(!items.length)container.innerHTML='<p class="empty">A blank room, ready for ideas.<br>Add furniture to start exploring.</p>';
 }
 else if(tab==='shortlist')container.innerHTML=roomShortlist().map(s=>{const p=product(s.id);return `<article class="shortlist-card"><div class="furniture-row">${thumb(p)}<div class="furniture-title"><strong>${esc(p.name)}</strong><small>${esc(p.brand)} · ${size(p)}</small><span class="row-price">${Number.isFinite(p.price)?money(p.price):'Price open'}</span></div></div><select data-status="${esc(p.id)}" aria-label="Shortlist status for ${esc(p.name)}">${['Considering','Favourite','Chosen','Pass'].map(v=>`<option ${s.status===v?'selected':''}>${v}</option>`).join('')}</select><textarea data-product-note="${esc(p.id)}" aria-label="Notes for ${esc(p.name)}" placeholder="Why it works, what to check…">${esc(s.note)}</textarea><div class="shortlist-links"><a href="${esc(safeURL(p.url))}" target="_blank" rel="noopener noreferrer">Product page ↗</a><button data-place="${esc(p.id)}">Try in room ＋</button><button data-unsave="${esc(p.id)}" aria-label="Remove ${esc(p.name)} from shortlist">×</button></div></article>`;}).join('')||'<p class="empty">Save a real product or add your own link.<br>Your options will stay here.</p>';
 else if(tab==='electronics')container.innerHTML='<p class="electronics-intro">Electronics are saved separately. Kitchen entries marked “model pending” are generic space allowances, not product selections. The LG C5 remains a living-room size reference.</p>'+state.electronics.map(e=>{const p=product(e.id),placed=layout().items.find(i=>i.productId===p.id||i.applianceIds?.includes(p.id));return `<article class="shortlist-card electronics-card"><div class="furniture-row">${thumb(p)}<div class="furniture-title"><strong>${esc(p.name)}</strong><small>${Math.round(p.w*1000)} W × ${Math.round(p.h*1000)} H × ${+(p.d*1000).toFixed(1)} D mm<br>${esc(p.brand)}</small><span class="row-price">${Number.isFinite(p.price)?money(p.price):'Price to source'}</span></div></div>${productLink(p)}<p class="electronics-detail">${esc(p.detail)}</p><select data-electronics-status="${esc(p.id)}" aria-label="Electronics status for ${esc(p.name)}">${['Size reference','Considering','Favourite','Chosen','Pass'].map(v=>`<option ${e.status===v?'selected':''}>${v}</option>`).join('')}</select><textarea data-electronics-note="${esc(p.id)}" aria-label="Electronics notes for ${esc(p.name)}">${esc(e.note)}</textarea>${placed&&p.id==='lg-c5-65'?`<div class="mount-controls" role="group" aria-label="TV mounting study"><button data-mount="wall" data-tv="${esc(placed.id)}" aria-pressed="${placed.mount!=='stand'}">Wall study</button><button data-mount="stand" data-tv="${esc(placed.id)}" aria-pressed="${placed.mount==='stand'}">On stand</button></div>`:''}<div class="shortlist-links">${placed?`<button data-select="${esc(placed.id)}">Edit placement ↗</button>`:`${p.pendingAppliance?`<button data-open-appliance="${esc(p.id)}">Open kitchen location ↗</button>`:`<button data-place="${esc(p.id)}">Place in room ＋</button>`}`}<button data-electronics-unsave="${esc(p.id)}" aria-label="Remove ${esc(p.name)} from electronics list">Remove from list</button></div></article>`;}).join('')+'<button class="quiet full" id="add-electronics">Save another electronic ＋</button>';
 else container.innerHTML='<p class="electronics-intro">Made for your flat. Keep the specification, maker, quote and progress together. Dimensions remain provisional until site confirmation.</p>'+state.customFurniture.map(c=>{const placed=layout().items.find(i=>i.referenceId===c.referenceId);const dimensions=c.referenceId.startsWith('kitchen-')||c.referenceId.startsWith('utility-')?c:placed||c;return `<article class="shortlist-card custom-furniture-card" data-custom-record="${esc(c.id)}"><div class="custom-card-header"><span class="overline">TO BE MADE · ${esc(c.room)}</span><h3>${esc(c.name)}</h3><strong>${size(dimensions)}</strong><small>${c.referenceId.startsWith('kitchen-')||c.referenceId.startsWith('utility-')?'Room envelope · module schedule in Layout & cabinet brief':'Width × depth × height · concept size'}</small></div><dl class="custom-specs"><dt>Material</dt><dd>${esc(c.material)}</dd><dt>Design</dt><dd>${esc(c.design)}</dd><dt>Finish</dt><dd>${esc(c.finish)}</dd>${c.finishStudy?`<dt>Current colour preview</dt><dd>${kitchenFinishes[c.finishStudy].name} · ${finishLinks(c.finishStudy)}</dd>`:''}<dt>Fixing</dt><dd>${esc(c.fixing)}</dd></dl><label class="custom-field">Progress<select data-custom-field="status" data-custom-id="${esc(c.id)}" aria-label="Custom furniture status for ${esc(c.name)}">${['Concept','Ready for quote','Quoted','Approved','In production','Installed'].map(v=>`<option ${c.status===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="custom-field">Maker / carpenter<input data-custom-field="supplier" data-custom-id="${esc(c.id)}" value="${esc(c.supplier)}" placeholder="Not shortlisted yet" aria-label="Maker for ${esc(c.name)}"></label><label class="custom-field">Indicative quote · ₹<input type="number" min="0" max="99999999" data-custom-field="quote" data-custom-id="${esc(c.id)}" value="${c.quote??''}" placeholder="Quote pending" aria-label="Quote for ${esc(c.name)}"></label><label class="custom-field">Notes / decisions<textarea rows="4" data-custom-field="notes" data-custom-id="${esc(c.id)}" aria-label="Custom furniture notes for ${esc(c.name)}">${esc(c.notes)}</textarea></label><div class="shortlist-links">${placed?`<button data-select="${esc(placed.id)}">View / edit in room ↗</button>`:'<span>Not placed in this layout</span>'}<button data-custom-brief="${esc(c.id)}">Edit specification</button></div><p class="custom-card-fine">Planning brief, not a fabrication drawing. Quotes are tracked here separately from the product subtotal.</p></article>`;}).join('');
}
function renderInspector(){const i=layout().items.find(i=>i.id===state.selected),el=$('#inspector');el.hidden=!i||(i.category==='electronics'?tab!=='electronics':tab!=='room');if(!i)return;el.innerHTML=`<div class="inspector-title"><div><h3>${esc(i.name)}</h3><p>${kitchenTypes.includes(i.type)?'CUSTOM MODULE · PROPOSED SIZE':i.type==='artset'?'PUBLISHED PRINT SIZE · HANGING STUDY':i.locked?'PUBLISHED PRODUCT SIZE · PROXY SHAPE':'ADJUSTABLE SIZE STUDY'}</p></div><button class="icon" id="deselect" aria-label="Deselect furniture">×</button></div><div class="inspector-source">${productLink(i)}${i.detail?`<p>${esc(i.detail)}</p>`:''}</div>${kitchenTypes.includes(i.type)?`<div class="module-controls"><label>Room<select data-module="zone"><option value="kitchen" ${i.zone!=='utility'?'selected':''}>Kitchen</option><option value="utility" ${i.zone==='utility'?'selected':''}>Utility</option></select></label><label>Purpose<select data-module="role">${['doors','drawers','sink','hob','pantry','waste','pullout','fridge','laundry','broom','island','breakfast','stool','rack','shelf','appliance','corner','blindcorner','oventower','appliancestation','hood','laundrystack','dishwasher','utilitysinkbin','moprack'].map(r=>`<option ${i.role===r?'selected':''}>${r}</option>`).join('')}</select></label></div>`:''}<div class="dimension-inputs">${[['w','Width'],['d','Depth'],['h','Height']].map(([v,label])=>`<label>${label} · cm<input type="number" data-dimension="${v}" min="${v==='h'?1:10}" max="800" step="1" value="${+(i[v]*100).toFixed(1)}" aria-label="${label} in centimetres" ${i.locked?'disabled':''}></label>`).join('')}</div><div class="position-inputs"><label>From left · cm<input id="position-x" data-position="x" type="number" step="5" value="${Math.round((i.x-info().x0)*100)}" aria-label="Centre from left in centimetres"></label><label>From top · cm<input id="position-z" data-position="z" type="number" step="5" value="${Math.round((i.z-info().z0)*100)}" aria-label="Centre from top wall in centimetres"></label><label>Rotation · °<input data-position="rotation" type="number" step="15" value="${i.rotation}" aria-label="Rotation in degrees"></label></div>${['tv','soundbar','art','artset','pendant','tablelamp','decor',...raisedKitchen].includes(i.type)?`<div class="elevation-input"><label>Bottom above floor · cm<input data-position="elevation" type="number" min="0" max="250" value="${Math.round((i.elevation||0)*100)}" aria-label="Bottom above floor in centimetres"></label></div>`:''}<div class="inspector-actions"><button id="rotate-selected">Rotate 15° ↻</button><button id="duplicate-selected">Duplicate ＋</button>${i.locked?'<button id="make-study">Make size study</button>':''}</div><p class="inspector-hint">${i.locked?'To test a different size, make an adjustable study. The original product stays in your shortlist.':'Changing this study’s dimensions does not change any real product listing.'}</p>`;}
function openModal(title,html,kicker='YOUR WORKSPACE'){$('#modal-kicker').textContent=kicker;$('#modal-content').innerHTML=`<h2>${esc(title)}</h2>`+html;$('#modal').showModal();}
function editCustomBrief(id){const c=state.customFurniture.find(c=>c.id===id);openModal('Custom furniture specification',`<p>${esc(c.name)} · ${size(c)}</p><form id="custom-brief-form" data-record="${esc(c.id)}"><div class="form-grid">${[['material','Material'],['design','Design / slat pattern'],['finish','Finish'],['fixing','Fixing / installation']].map(([key,label])=>`<label class="span2">${label}<textarea name="${key}" rows="2" maxlength="3000">${esc(c[key])}</textarea></label>`).join('')}</div><button type="submit" class="primary">Save specification</button></form>`,'CUSTOM FURNITURE / TO BE MADE');}
function utilityFitHTML(l){const gaps=kitchenClearance(l.items),open=utilityOpeningClearance(l.items),cm=n=>n===null?'—':Math.round(n*100)+' cm';return `<div class="check-row">Smallest closed utility aisle at opposing units: ≈ ${cm(gaps.utility)}.<br>Remaining width with the dishwasher's 60 cm opening allowance: ≈ ${cm(open.dishwasher)}.<br>Remaining width with the laundry's 60 cm opening allowance: ≈ ${cm(open.laundry)}.</div><p class="fine">These are floor-envelope studies, not actual door or occupant measurements. The laundry allowance narrows the front aisle; do not treat it as a clear through-passage while loading. Rectangles do not establish that two appliance doors, baskets and a person can operate simultaneously. Confirm with the actual models.</p>`;}
function utilityBriefHTML(l){return `<h3>Separate washer, dryer and dishwasher</h3><p>Utility: 256.5 × 182.9 cm from the builder plan. Start with a front-loading washer and a separate dryer above it, with a compatible manufacturer-approved stacking kit. The stacked arrangement is agreed; the exact front-load washer, separate dryer and stacking kit are still to select.</p><div class="module-schedule">${l.items.filter(i=>i.zone==='utility').map(i=>`<div><span>${esc(i.name)}</span><strong>${size(i)}</strong><small>${i.elevation?'Bottom '+Math.round(i.elevation*100)+' cm above floor':'Floor standing'}</small></div>`).join('')}</div><h3>Placement and storage</h3><p>The laundry stack sits left near the entrance. The dishwasher sits farther back on the right, beside a sink and bin unit. A dedicated rack at the rear left holds the mop, broom and dustpan above a removable drip area. The raised closed cupboard on the right stores cleaning supplies. No new floor-standing bin occupies the aisle.</p><h3>Door-opening study</h3>${utilityFitHTML(l)}<p>The dashed rectangles show 60 cm opening / working allowances at the laundry and dishwasher fronts. Their positions are staggered. Current indicative gaps and the remaining dishwasher passage are in View checks; they update when modules move. A washing-machine door can narrow the front aisle, so do not assume a clear bypass while loading. Actual door hinges, baskets, user standing space and service removal need the chosen models.</p><h3>What still needs checking</h3><p>The 70 × 80 × 185 cm stack is a reserve, not a confirmed installation envelope. Confirm model / stacking-kit compatibility, ventilation, dryer condensate / tank access, dedicated electrical requirements and machine levelling. The dishwasher bay needs actual hose / rear / top clearances. Confirm water, waste, floor traps, weather exposure, window travel and the scaled utility doorway. Bin and trap / cleaning access must be designed within the sink module; neither the bin capacity nor internal fitting is fixed.</p><p>Keep the window serviceable, provide a removable wet-tool tray, and choose cupboard anchors, edge sealing and any child-resistant latch with the maker. Appliance and cabinetry prices remain pending. The kitchen units and their appliance locations are retained from the preceding layout.</p><h3>Manufacturer planning references</h3><p><a href="https://www.bosch-home.in/en/category-page/washer-dryer/tumble-dryers" target="_blank" rel="noopener noreferrer">Bosch India · compatible dryer stacking ↗</a> · <a href="https://media3.bosch-home.com/Documents/specsheet/en-IN/SMS66GI01I.pdf" target="_blank" rel="noopener noreferrer">Bosch India · example 60 cm dishwasher dimensions ↗</a></p>`;}
function applianceBriefHTML(){return `<h3>Your full appliance list</h3><div class="module-schedule">${applianceRequirements.map(p=>`<div><span>${esc(p.name)}</span><strong>${size(p)}</strong><small>${esc(p.detail)}</small></div>`).join('')}</div><h3>Cooktop wall · important geometry</h3><p>This proposal uses the bottom kitchen wall in the drawing, to the right of the utility doorway. The estimated 105 cm opening leaves about 87 cm of directly shared utility wall on the left and 64 cm on the right. The 75 cm-class hob uses the right-hand wall continuation, which extends beyond the utility boundary beside the service / shaft area. It does not fit wholly on the short shared partition. Verify continuous backing and the measured door position. No door is moved in this study.</p><p>Allow a hood matched to the hob and an installer-confirmed duct to an approved outside outlet. A utility-side location does not establish an exhaust route. Gas / induction, electrical supply, countertop cut-out / thickness and heat clearances follow the selected models. The hood volume here starts 75 cm above the worktop for illustration; its final height is model-specific.</p><h3>Counter space and daily use</h3><p>The 110 cm station parks a 30 cm mixer, 25 cm juicer and 35 cm coffee-machine allowance with 20 cm total gaps. These are body / parking allowances; jar removal, tanks, cords, ingredients and operating space are not verified. Larger models can exceed them. The separate 90 cm main prep counter stays clear; corner / landing surfaces add secondary space. Store the mixer or juicer below when more room is needed. A standalone coffee grinder or larger espresso setup needs extra allocation.</p><p><a href="https://www.elicaindia.com/service-correct-installation.aspx" target="_blank" rel="noopener noreferrer">Elica · installation requirements ↗</a> · <a href="https://www.bosch-home.in/en/category/cooking-baking/built-in-ovens" target="_blank" rel="noopener noreferrer">Bosch India · 60 cm oven examples ↗</a></p>`;}
function showKitchenBrief(){
 const l=layout(),k=kitchenIdeas[l.kitchenScheme],finish=kitchenFinishes[l.kitchenFinish],g=kitchenClearance(l.items),cm=n=>n===null?'—':Math.round(n*100)+' cm';
 openModal(k.label+' · cabinet brief',`<div class="scheme-modal-palette">${(finish?[finish.base,finish.upper,finish.top]:k.swatches).map(c=>`<i style="background:${c}"></i>`).join('')}<span>Proposed finishes · custom modular cabinetry</span></div><p>${esc(l.description)}</p><div class="check-row">${esc(k.tradeoff)}</div>${l.kitchenFinish?`<h3>Cabinet colour preview · ${kitchenFinishes[l.kitchenFinish].name}</h3><p>${esc(finishBrief(l.kitchenFinish))}</p>${finishLinks(l.kitchenFinish)}`:''}<h3>What changes</h3><p>Existing countertops may be altered. Every cabinet, tall bank, return and island shown is proposed. A breakfast bar is not part of the existing flat. ${l.breakfastMode?'This variation adds a 25 cm overhang and two stools; the west side is seating space and has no protected through-route.':'The primary layouts have no breakfast seating.'}</p><h3>Space to work</h3><p>Working gap ≈ ${cm(g.working)} · utility gap ≈ ${cm(g.utility)}${g.end===null?'':' · island utility-end passage ≈ '+cm(g.end)}. A 60 cm opening / working rectangle is checked in front of each floor cabinet. A 120 cm island aisle is a planning target from the linked IKEA guide; actual appliance doors and occupied seating still need model-specific checks.</p><h3>Live module schedule · outer W × D × H</h3><p class="fine">Dimensions include the shown fronts / top. Fillers, corner access and carcass sizes are for the maker to develop. Raised modules show bottom elevation.</p>${['kitchen','utility'].map(zone=>`<h4>${zone==='kitchen'?'Kitchen':'Utility'}</h4><div class="module-schedule">${l.items.filter(i=>i.zone===zone).map(i=>`<div><span>${esc(i.name)}</span><strong>${size(i)}</strong><small>${i.elevation?'Bottom '+Math.round(i.elevation*100)+' cm above floor':'Floor standing'}</small></div>`).join('')}</div>`).join('')}${l.appliancePlan?applianceBriefHTML():''}<h3>Cabinet construction & organisation</h3><p>Illustrative ${l.appliancePlan?'65':'60'} cm base depth, 90 cm worktop height, 35 cm upper depth and 220 cm tall units; lofts stay below the 274 cm ceiling. Use accessible drawers for daily utensils, sink-side waste storage, sealed edges and removable service panels. Corner fittings, hinges, runners, internal bins, finish samples and final substrate remain to choose with the maker. These are custom concepts, not an IKEA product order.</p>${l.utilityPlan?utilityBriefHTML(l):''}<h3>Utility services</h3><p>${l.utilityPlan?'A separate washer / dryer stack, dishwasher and sink / bin are proposed.': 'Laundry reserve left;'} ${l.utilityPlan?'':'wash sink and folding / cleaning counter right.'} ${l.utilityPlan?'Keep cleaning chemicals in the raised cupboard and wet tools in their dedicated drip area.':l.kitchenScheme==='island'?'A fold-down sorting shelf and ceiling drying rack are new proposals. Check the rack’s working height, window movement and clothes clearance.':'Broom / mop storage stays away from the doorway. Raised cabinets keep cleaning supplies above the worktop.'} Preserve drain and plumbing access; exact service points are unknown.</p><h3>Before we finalise</h3><p>Measure finished wall lengths, counter height, door / window openings and swings. Mark water, waste, gas, sockets, exhaust and floor traps. Fridge, hob, hood, oven, dishwasher and laundry appliances need their actual models before openings or ventilation are fixed. Sink and hob shapes currently mark zones only. Utility opening is approximately 105 cm scaled from the drawing, not site measured.</p><h3>Quotes & decisions</h3><p>Kitchen and utility packages for each alternative are saved under Custom furniture, with specification, maker, quote, progress and notes. Package dimensions describe the room envelope; this schedule describes each module. Compare alternatives separately. Prices are pending; appliance costs are excluded.</p><h3>References</h3>${l.kitchenFinish?finishLinks(l.kitchenFinish):`<p><a href="${k.reference}" target="_blank" rel="noopener noreferrer">${esc(k.referenceTitle)} ↗</a></p>`}${kitchenSources.map(([t,u])=>`<p><a href="${u}" target="_blank" rel="noopener noreferrer">${t} ↗</a></p>`).join('')}`,'KITCHEN + UTILITY / PROPOSED MODULAR DESIGN');
}
function showKitchenChecks(problems){const g=kitchenClearance(layout().items),cm=n=>n===null?'—':Math.round(n*100)+' cm';openModal('Room to cook, wash and move.',`<p>Kitchen: 401.3 × 269.2 cm. Utility: 256.5 × 182.9 cm. Builder dimensions are used as provisional internal sizes.</p><div class="check-row">Working aisle ≈ ${cm(g.working)}<br>Utility working gap ≈ ${cm(g.utility)}${g.end===null?'':'<br>Island-end passage ≈ '+cm(g.end)}</div>${problems.length?problems.map(p=>`<div class="check-row issue">${esc(p.text)}</div>`).join(''):'<div class="check-row">✓ Shown modules remain in their room envelopes.<br>✓ No cabinet volumes overlap.<br>✓ Kitchen entry and estimated utility approach are clear.<br>✓ Shown floor modules have a 60 cm opening allowance clear of other pieces (blind corner accessed via return).</div>'}${layout().utilityPlan?utilityFitHTML(layout()):''}<p>For an island, we compare the working gap with a 120 cm target and the utility-end route with 90 cm. The parallel / tall-bank arrangement also accounts for the deeper fridge reserve. Open drawers and appliance doors can reduce the remaining aisle substantially.</p><p class="fine">Upper cabinets, shelves and drying racks are excluded from floor-route checks, but their heights and volume collisions are checked. Appliance opening / ventilation, occupied stools, knee space, splash / heat clearances, corner hardware, actual window travel and services are not verified. When present, breakfast stools occupy the west side; use the east route. Utility doorway position is scaled. Plan view hides raised storage so the floor layout is readable. All clearances update when you move modules.</p><p><a href="${kitchenSources[0][1]}" target="_blank" rel="noopener noreferrer">Planning reference · 120 cm island aisle ↗</a></p>`,'KITCHEN + UTILITY / CONCEPT CHECKS');}
function showSchemeDetails(){if(activeRoom()==='kitchen'){showKitchenBrief();return;}const l=layout(),palette=schemePalettes[l.scheme];if(!palette)return;const cabinet=l.items.find(i=>i.type==='cabinet'),lamp=l.items.find(i=>i.type==='pendant');openModal(l.name.replace(/^\d+ · /,''),`<div class="scheme-modal-palette">${palette.swatches.map(c=>`<i style="background:${c}"></i>`).join('')}<span>${palette.label}</span></div><p>${esc(l.description)}</p><h3>Crockery, within reach</h3><p>${esc(cabinet?.name||'No cupboard placed')}${cabinet?` · ${size(cabinet)}. ${esc(cabinet.detail)}`:''}</p><h3>Light for everyday meals</h3><p>${esc(lamp?.name||'No pendant placed')}. Suspension is currently studied with the shade bottom 160 cm above the floor, 85 cm above the 75 cm table. Warm evening light is illustrative. Confirm the ceiling point, bulb choice and cupboard-side socket.</p><h3>Art & finishing touches</h3><p>The listed prints are real products with their own photos and links. Their 3D artwork is a simplified sketch. Paired prints are one priced pack. Crockery, runner, vase and a potted herb are illustrative styling; they still need sourcing. Wall colour is a paint study. Tiles stay as planned.</p><h3>Four daily, guests occasionally</h3><p>${l.scheme==='sunlit'?'This table is fixed at four seats. Choose an extendable scheme if six is essential.':'Use Six-seat check to see this room with its table extended and two extra chairs. It is a separate saved study, with any restricted passage or cupboard access flagged.'}</p><h3>Included product links</h3><div class="scheme-product-links">${[...new Map(l.items.filter(i=>i.url).map(i=>[i.productId,i])).values()].map(i=>`<p>${productLink(i)} <span>${money(i.price)}</span></p>`).join('')}</div><p class="fine">Subtotal covers the listed furniture, fixtures and art in this arrangement. Bulbs, ceiling hardware, installation, paint, loose styling, delivery and assembly remain extra. Published product sizes are checked; apartment openings and finished site dimensions remain provisional.</p>`,'DINING / COMPLETE ROOM IDEA');}
function showReference(){if(activeRoom()==='kitchen'&&layout().kitchenFinish){showFinishDetails();return;}if(activeRoom()==='kitchen'){const k=kitchenIdeas[layout().kitchenScheme];openModal(k.referenceTitle,`<p>Colour and storage inspiration from an IKEA kitchen reference. Your layout is a custom modular study adapted to this apartment, with appliance models still open.</p><p>${esc(k.tradeoff)}</p><p><a href="${k.reference}" target="_blank" rel="noopener noreferrer">Open the real kitchen reference ↗</a></p>`,'KITCHEN / STYLE REFERENCE');return;}const p=projects.find(p=>p.id===layout().project);openModal(p.name,`<img class="reference-image" src="assets/images/${p.image}" alt="${esc(p.title)}"><p>${esc(p.takeaway)}</p><p class="credit">${esc(p.credit)}</p><p><a href="${p.url}" target="_blank" rel="noopener noreferrer">Explore ${esc(p.title)} ↗</a></p>`,'REAL HOME / DESIGN REFERENCE');}
function showLibrary(){if(activeRoom()==='kitchen'){openModal('Add a cabinet module',`<p>Custom size studies. Add a module, select it to change dimensions and position, then choose its room and purpose.</p><div class="library-grid">${kitchenTemplates.map(p=>`<article class="library-card">${thumb(p)}<div><strong>${p.name}</strong><small>${size(p)} · custom</small><button data-kitchen-template="${p.id}">Add module ＋</button></div></article>`).join('')}</div><p class="fine">Appliance models and installation clearances will be added when you provide them. Countertops, sink and hob positions are proposals.</p>`,'KITCHEN / MODULAR STUDIES');return;}openModal('Find a place for it.',`<p>Start with a real product at its published size, or an adjustable study. Every piece here is a simplified model.</p><h3>Real options to compare</h3><div class="library-grid">${[...products,...electronicsProducts,...state.customProducts].filter(inRoom).map(p=>`<article class="library-card">${thumb(p)}<div><strong>${esc(p.name)}</strong><small>${size(p)}<br>${Number.isFinite(p.price)?money(p.price):'Price open'}</small><button data-place="${esc(p.id)}">Place in room ＋</button><a href="${esc(safeURL(p.url))}" target="_blank" rel="noopener noreferrer">View ↗</a></div></article>`).join('')}</div><h3>Just exploring sizes?</h3><div class="library-grid">${templates.filter(p=>activeRoom()==='living'||['diningtable','diningchair','console','lamp'].includes(p.type)).map(p=>`<article class="library-card">${thumb(p)}<div><strong>${esc(p.name)}</strong><small>Adjustable · ${size(p)}</small><button data-template="${p.id}">Add size study ＋</button></div></article>`).join('')}</div><h3>Found something elsewhere?</h3><p>Save its link and enter the outer dimensions from the listing. We can refine the shape together later.</p><form id="product-form"><div class="form-grid"><label class="span2">Product name<input required name="name" maxlength="100" placeholder="e.g. Compact three-seat sofa"></label><label class="span2">Product link<input type="url" required name="url" placeholder="https://…"></label><label>Save in<select name="category"><option value="furniture">Furniture shortlist</option><option value="electronics">Electronics list</option></select></label><label>Item type<select name="type">${allowedTypes.map(v=>`<option value="${v}">${v==='woodsofa'?'Timber sofa':v==='diningtable'?'Dining table':v==='diningchair'?'Dining chair':v==='artset'?'Framed art pair':v==='tablelamp'?'Table lamp':v[0].toUpperCase()+v.slice(1)}</option>`).join('')}</select></label><label>Listed price · ₹ (optional)<input name="price" type="number" min="0" max="10000000"></label><div class="thirds">${[['w','Width'],['d','Depth'],['h','Height']].map(([n,l])=>`<label>${l} · cm<input name="${n}" type="number" min="1" max="800" required step=".1"></label>`).join('')}</div></div><p class="form-error" id="product-error"></p><button class="primary" type="submit">Save to shortlist</button></form>`,'FURNITURE / YOUR OPTIONS');}
function place(id,template=false){const p=template?templates.find(p=>p.id===id):product(id);if(!p)return;const already=p.category==='electronics'&&layout().items.find(i=>i.productId===id);if(already){state.selected=already.id;tab='electronics';render();$('#modal').close();return;}change(()=>{const item={...structuredClone(p),id:uid(),productId:p.verified?p.id:null,referenceId:p.id,elevation:['art','artset'].includes(p.type)?1.6:p.type==='pendant'?1.6:p.type==='tablelamp'?1.1:0,room:activeRoom(),x:activeRoom()==='dining'?5.38:p.type==='tv'?.10:1.75,z:activeRoom()==='dining'?4.43:p.type==='tv'?3.6:4.65,rotation:p.type==='tv'?90:0,locked:!!p.verified};layout().items.push(item);state.selected=item.id;state.finalised=false;const list=p.category==='electronics'?state.electronics:state.shortlist;if(!template&&!list.some(s=>s.id===p.id))list.push({id:p.id,status:'Considering',note:''});tab=p.category==='electronics'?'electronics':'room';},'Added to this layout. Drag it into place.');$('#modal').close();}
function showChecks(){const problems=checks(layout().items,activeRoom());if(activeRoom()==='kitchen'){showKitchenChecks(problems);return;}if(activeRoom()==='dining'){const d=diningClearance(layout().items);openModal('Space for people, too.',`<p>The dining area is 406.4 × 264.2 cm from your builder drawing. The dashed outlines move each chair 35 cm back from its shown position; this is a planning allowance, not a measured occupant envelope.</p><div class="check-row">South clear gap at shown positions: ≈ ${Math.round(d.seated*100)} cm.<br>South gap with chairs pulled back: ≈ ${Math.round(d.pulled*100)} cm.</div>${problems.length?problems.map(p=>`<div class="check-row issue">${esc(p.text)}</div>`).join(''):'<div class="check-row">✓ Furniture stays within the dining study boundary.<br>✓ No placed / pulled-back chair footprints overlap other pieces.<br>✓ Crockery cabinet access allowance is clear, where present.<br>✓ The 90 cm southern passage guide is clear in this study.</div>'}<p class="fine">The south strip connects living, kitchen and bedroom circulation. Door approaches use estimated positions from the drawing. Cabinet access uses a 60 cm rectangle in front of the cupboard, including the hinged-door allowance. Wall art, suspended lights and cupboard-top styling are excluded from floor checks. Checks do not verify knees, table legs, actual door swing, accessibility or site fit. Dining and living retain independent saved layouts.</p>`,'DINING / SPACE TO SIT & MOVE');return;}openModal('A little breathing room.',`<p>These checks compare furniture footprints with the living-room boundary, a 60 cm balcony-access guide and a 90 cm foyer-to-dining guide. They help spot obvious conflicts; comfort, door travel and exact site dimensions still need judgment.</p>${problems.length?problems.map(p=>`<div class="check-row issue">${esc(p.text)}</div>`).join(''):'<div class="check-row">✓ No furniture footprint overlaps found.<br>✓ No pieces cross the room boundary.<br>✓ The 60 cm balcony and 90 cm dining guides are clear.</div>'}<p class="fine">Rugs are allowed beneath furniture; raised electronics do not count as floor obstructions. The jali may sit on the living/dining boundary strip. Chaise checks use an L-shaped footprint. All other pieces use rectangular outer footprints. A clear guide is a planning aid, not a complete accessibility assessment.</p>`,'LAYOUT / FOOTPRINT CHECKS');}
function exportBackup(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='my-apartment-workspace.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Workspace backup downloaded.');}
function rotate(){const i=layout().items.find(i=>i.id===state.selected);if(i)change(()=>{i.rotation=(i.rotation+15)%360;state.finalised=false});}
function doUndo(){if(!undo.length)return;state=normalise(JSON.parse(undo.pop()));persist();render();scene.setView(state.view);toast('Last change undone.');}
$('#directions').addEventListener('click',e=>{const b=e.target.closest('[data-layout]');if(!b)return;openLayout(b.dataset.layout);});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
 if(b.dataset.room){if(state.view==='overall')state.view='plan';const id=state.rooms[b.dataset.room]?.lastLayout||state.layouts.find(l=>roomOf(l)===b.dataset.room)?.id;if(id)openLayout(id);}
 if(b.dataset.kitchenFinish){change(()=>{applyKitchenFinish(state,layout(),b.dataset.kitchenFinish);state.finalised=false;},'Cabinet colour preview saved for this layout.');}
 if(b.id==='utility-details')openModal('Utility · laundry, dishes & cleaning',utilityBriefHTML(layout()),'UTILITY / SPACE & STORAGE');
 if(b.id==='finish-details')showFinishDetails();
 if(b.dataset.openAppliance){const target=state.layouts.find(l=>(l.appliancePlan||l.utilityPlan)&&l.items.some(i=>i.applianceIds?.includes(b.dataset.openAppliance)));if(target){openLayout(target.id);state.selected=target.items.find(i=>i.applianceIds?.includes(b.dataset.openAppliance)).id;tab='room';render();}}
 if(b.dataset.focus)setKitchenFocus(b.dataset.focus);
 if(b.dataset.kitchenTemplate){const p=kitchenTemplates.find(p=>p.id===b.dataset.kitchenTemplate);change(()=>{const i={...structuredClone(p),id:uid(),zone:kitchenPanelFocus==='utility'?'utility':'kitchen',referenceId:kitchenPanelFocus==='utility'?(layout().utilityPlan?'utility-complete':'utility-'+layout().kitchenScheme):'kitchen-'+layout().kitchenScheme,x:kitchenPanelFocus==='utility'?3.10:3.5,z:kitchenPanelFocus==='utility'?10.0:7.6,rotation:0,locked:false};layout().items.push(i);if(layout().kitchenFinish)applyKitchenFinish(state,layout(),layout().kitchenFinish);state.selected=i.id;state.finalised=false;tab='room';});$('#modal').close();}
 if(b.id==='breakfast-study'){if(layout().breakfastMode)openLayout(layout().sourceLayout);else{const l=breakfastKitchen(state);if(l)openLayout(l.id);}}
 if(b.id==='six-seat'){if(layout().guestMode)openLayout(layout().sourceLayout);else{const l=guestScheme(state);if(l)openLayout(l.id);}}
 if(b.id==='scheme-details')showSchemeDetails();
 if(b.dataset.select){state.selected=b.dataset.select;tab=layout().items.find(i=>i.id===state.selected)?.category==='electronics'?'electronics':'room';render();$('#drag-tip').hidden=state.view==='eye';}
 if(b.dataset.remove)change(()=>{layout().items=layout().items.filter(i=>i.id!==b.dataset.remove);if(state.selected===b.dataset.remove)state.selected=null;state.finalised=false},'Removed. Undo is available.');
 if(b.dataset.place)place(b.dataset.place);if(b.dataset.template)place(b.dataset.template,true);
 if(b.dataset.unsave)change(()=>state.shortlist=state.shortlist.filter(s=>s.id!==b.dataset.unsave),'Removed from shortlist.');
 if(b.dataset.view){state.view=b.dataset.view;if(state.view==='overall')state.selected=null;persist();render();scene.setView(state.view);}
 if(b.dataset.tab){tab=b.dataset.tab;render();}
 if(b.dataset.customSpec){tab='custom';state.selected=null;render();const record=[...document.querySelectorAll('[data-custom-record]')].find(v=>v.dataset.customRecord===b.dataset.customSpec);record?.scrollIntoView({block:'start'});}
 if(b.dataset.customBrief)editCustomBrief(b.dataset.customBrief);
 if(b.dataset.passage){change(()=>{state.active=passageLayout(state,b.dataset.passage).id;state.selected=null;state.finalised=false},'Passage option saved; your original lounge is retained.');$('#modal').close();}
 if(b.dataset.mount)change(()=>{const tv=layout().items.find(i=>i.id===b.dataset.tv),bench=layout().items.find(i=>i.type==='console');tv.mount=b.dataset.mount;tv.w=1.441;tv.d=tv.mount==='stand'?.23:.0451;tv.h=tv.mount==='stand'?.88:.826;tv.elevation=tv.mount==='stand'?(bench?.h||.38):.68;tv.x=tv.mount==='stand'?(bench?.x||.22):.10;tv.z=bench?.z||3.6;tv.rotation=90;state.finalised=false;});
 if(b.dataset.electronicsUnsave)change(()=>state.electronics=state.electronics.filter(e=>e.id!==b.dataset.electronicsUnsave));
 if(b.id==='deselect'){state.selected=null;render();}
 if(b.id==='rotate-selected')rotate();
 if(b.id==='duplicate-selected'){const i=layout().items.find(i=>i.id===state.selected);change(()=>{const n={...structuredClone(i),id:uid(),x:i.x-.15,z:i.z+.20};layout().items.push(n);state.selected=n.id;state.finalised=false});}
 if(b.id==='make-study'){change(()=>{const i=layout().items.find(i=>i.id===state.selected);i.locked=false;i.verified=false;i.productId=null;i.price=null;i.name+=' · size study';},'Product retained in shortlist; this copy is adjustable.');}
});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.module){change(()=>{const i=layout().items.find(i=>i.id===state.selected);i[el.dataset.module]=el.value;if(el.dataset.module==='zone')i.referenceId=el.value+'-'+layout().kitchenScheme;state.finalised=false;});}if(el.dataset.dimension){const value=Number(el.value)/100;if(!Number.isFinite(value)||value<.01||value>8){toast('Enter a size between 1 and 800 cm.');renderInspector();return;}change(()=>{const i=layout().items.find(i=>i.id===state.selected);i[el.dataset.dimension]=value;const custom=joineryFor(i);if(custom&&!kitchenTypes.includes(i.type))custom[el.dataset.dimension]=value;state.finalised=false});}
 if(el.dataset.position){const val=Number(el.value);if(!Number.isFinite(val)||Math.abs(val)>10000)return;change(()=>{const i=layout().items.find(i=>i.id===state.selected);i[el.dataset.position]=el.dataset.position==='rotation'?val:val/100+(el.dataset.position==='z'?info().z0:el.dataset.position==='x'?info().x0:0);state.finalised=false});}
 if(el.dataset.customField&&['status','quote'].includes(el.dataset.customField)){const c=state.customFurniture.find(c=>c.id===el.dataset.customId);const value=el.dataset.customField==='quote'?(el.value===''?null:Number(el.value)):el.value;if(el.dataset.customField==='quote'&&value!==null&&(!Number.isFinite(value)||value<0||value>=1e8)){toast('Enter a valid quote or leave it blank.');return;}change(()=>c[el.dataset.customField]=value);}
 if(el.dataset.electronicsStatus)change(()=>state.electronics.find(e=>e.id===el.dataset.electronicsStatus).status=el.value);
 if(el.dataset.status)change(()=>state.shortlist.find(s=>s.id===el.dataset.status).status=el.value);
});
document.addEventListener('input',e=>{if(e.target.dataset.customField&&['supplier','notes'].includes(e.target.dataset.customField)){state.customFurniture.find(c=>c.id===e.target.dataset.customId)[e.target.dataset.customField]=e.target.value;persist();}if(e.target.dataset.electronicsNote){state.electronics.find(s=>s.id===e.target.dataset.electronicsNote).note=e.target.value;persist();}if(e.target.dataset.productNote){state.shortlist.find(s=>s.id===e.target.dataset.productNote).note=e.target.value;persist();}});
$('#room-note').addEventListener('input',e=>{state.roomNote=e.target.value;persist();});
$('#reference-button').addEventListener('click',showReference);$('#passage-options').addEventListener('click',()=>openModal('Keep the route to dining open.',`<p>The saved lounge has an ottoman in the crossing route. Each alternative keeps your original arrangement and adds a short jali at the living/dining boundary.</p><div class="passage-options">${passageOptions.map(o=>`<article class="check-row"><span class="overline">${esc(o.label)}</span><h3>${esc(o.name)}</h3><p>${esc(o.description)}</p><button class="quiet" data-passage="${o.id}">Open this option ↗</button></article>`).join('')}</div><p class="fine">The 145 × 8 × 210 cm jali is a provisional custom joinery study, with open slats and a short run that stops before the dining passage. Final design and fixing details are to be developed.</p>`,'LIVING / PASSAGE OPTIONS'));$('#add-item').addEventListener('click',showLibrary);$('#close-modal').addEventListener('click',()=>$('#modal').close());
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
$('#fit-button').addEventListener('click',showChecks);$('#undo').addEventListener('click',doUndo);$('#reset-camera').addEventListener('click',()=>scene.reset());$('#dimensions-toggle').addEventListener('click',()=>{dimensions=!dimensions;scene.dimensions(dimensions);$('#dimensions-toggle').classList.toggle('active',dimensions);$('#dimensions-toggle').setAttribute('aria-pressed',dimensions)});
$('#export').addEventListener('click',exportBackup);$('#import-button').addEventListener('click',()=>$('#import-file').click());
$('#measurements').addEventListener('click',()=>openModal('What we know. What we estimate.',`<p>Room sizes come from the builder’s drawing. We currently use them as clear internal sizes; this has not been verified on site. Unlabelled openings are scaled from the drawing.</p>${measurementNotes.map(([a,b,c])=>`<div class="measurement-row"><span>${esc(a)}</span><strong>${esc(b)}</strong><span>${esc(c)}</span></div>`).join('')}<p class="fine" style="margin-top:15px">Window/door heights and sun direction are staged. Tiles are confirmed throughout except the main bedroom; tile colour and size remain visual studies. Furniture artwork in the original plan is not a fixed requirement.</p>`,'APARTMENT / MEASUREMENT RECORD'));
