$('#more').addEventListener('click',()=>openModal('Your ideas, kept together.',`<p>${server?'Furniture positions, sizes, shortlists and notes save to your local project and this browser.':'Your edits save in this browser on this device. They do not sync to GitHub or other devices.'} Export a backup to keep another copy or transfer your choices.</p><h3>Room notes</h3><textarea id="mobile-room-note" rows="4" aria-label="Room notes">${esc(state.roomNote)}</textarea><div class="backup-actions"><button class="quiet" id="menu-export">Export backup ↗</button><button class="quiet" id="menu-import">Import backup</button><button class="quiet" id="menu-finalise">${state.finalised?'Reopen this room':'Mark this room as finalised'}</button></div><h3>Sources & limitations</h3><p>Project references are linked in each direction. Furniture photos and dimensions come from the linked manufacturer pages; prices were checked ${checked}. Delivery and assembly are excluded, and local availability is unverified.</p><p style="margin-top:10px"><a href="CREDITS.md" target="_blank">Asset sources and credits ↗</a></p>`));
document.addEventListener('input',e=>{if(e.target.id==='mobile-room-note'){state.roomNote=e.target.value;persist();$('#room-note').value=state.roomNote}});
document.addEventListener('click',e=>{const id=e.target.closest('button')?.id;if(id==='add-electronics'){showLibrary();$('#product-form [name=category]').value='electronics';$('#product-form [name=type]').value='soundbar';$('#product-form').scrollIntoView({block:'start'});}if(id==='menu-export')exportBackup();if(id==='menu-import')$('#import-file').click();if(id==='menu-finalise'){change(()=>state.finalised=!state.finalised);$('#modal').close();}});
document.addEventListener('submit',e=>{
 if(e.target.id==='custom-brief-form'){e.preventDefault();const c=state.customFurniture.find(c=>c.id===e.target.dataset.record),form=new FormData(e.target);change(()=>{for(const key of ['material','design','finish','fixing'])c[key]=String(form.get(key)||'').slice(0,key==='design'?3000:2000)},'Custom specification saved.');$('#modal').close();}
 if(e.target.id==='layout-form'){e.preventDefault();const name=new FormData(e.target).get('name').trim();if(!name)return;change(()=>{const l=structuredClone(layout());if(activeRoom()==='kitchen')l.sourceLayout=layout().id;l.id=uid();l.name=name;l.description='Your saved variation. Add a room note to tell me what you want to explore next.';state.layouts.push(l);state.active=l.id;state.selected=null;state.finalised=false},'Layout saved alongside your other ideas.');$('#modal').close();}
 if(e.target.id==='product-form'){e.preventDefault();const f=new FormData(e.target),url=safeURL(f.get('url'));if(!url){$('#product-error').textContent='Please enter an http or https product link.';return;}const p={id:uid(),name:String(f.get('name')).trim(),brand:'Your saved option',type:f.get('type'),room:activeRoom(),category:f.get('category')==='electronics'||['tv','soundbar'].includes(f.get('type'))?'electronics':'furniture',w:Number(f.get('w'))/100,d:Number(f.get('d'))/100,h:Number(f.get('h'))/100,price:f.get('price')!==''?Number(f.get('price')):null,color:'#c7b9a2',url,verified:false,detail:'Dimensions and price entered by you; not independently verified.'};if(!p.name||[p.w,p.d,p.h].some(v=>!Number.isFinite(v)||v<.01||v>8)){$('#product-error').textContent='Enter a name and dimensions from 1 to 800 cm.';return;}change(()=>{state.customProducts.push(p);(p.category==='electronics'?state.electronics:state.shortlist).push({id:p.id,status:'Considering',note:''});tab=p.category==='electronics'?'electronics':'shortlist'},'Saved to your shortlist.');$('#modal').close();}
});
$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2e6)throw Error('This backup is too large.');const next=upgradeWorkspace(normalise(JSON.parse(await file.text())));change(()=>state=next,'Workspace imported. Undo is available.');scene.setView(state.view);$('#modal').close();}catch(error){toast(error.message||'This backup could not be read.')}e.target.value='';});
document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||$('#modal').open)return;if(state.view==='overall')return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();doUndo();}else if(e.key.toLowerCase()==='r')rotate();else if(e.key==='Escape'){state.selected=null;render();}});
window.addEventListener('pagehide',()=>{try{localStorage.setItem(key,JSON.stringify(state))}catch{}if(server)fetch(storageOptions.api,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(state),keepalive:true}).catch(()=>{});});
// Read-only diagnostics support repeatable checks; the workspace itself is also saved as JSON.
window.planner={getState:()=>structuredClone(state),getChecks:()=>checks(layout().items,activeRoom()),diagnostics:()=>scene.diagnostics()};
load();
